import re

def find_empty_except(code):
    lines = code.split("\n")
    hits = []
    for i, line in enumerate(lines):
        if re.match(r"\s*except\b", line):
            body = []
            for nxt in lines[i+1:]:
                if nxt.strip() and not nxt.startswith((" ", "\t")):
                    break
                body.append(nxt.strip())
            meaningful = [b for b in body if b and b not in ("pass",) and not b.startswith("#") and b != "return None"]
            if not meaningful:
                hits.append(i + 1)
    return hits

def suppresses_security(code):
    lines = code.split("\n")
    empty = set(find_empty_except(code))
    for ln in empty:
        j = ln - 2
        while j >= 0:
            if re.search(r"(?i)(auth|permission|verify)", lines[j]):
                return True
            if re.match(r"\s*try\b", lines[j]):
                break
            j -= 1
    return False

import re

def review_cmd(cmd, whitelist, patterns):
    first = cmd.strip().split()[0] if cmd.strip() else ""
    if first in whitelist:
        return "allow"
    verdict = "review"
    for pat, level in patterns:
        if re.search(pat, cmd):
            if level == "critical":
                return "block"
            verdict = "review"
    return verdict

def mutation_score(impl, mutants, tests):
    killed = 0
    for code in mutants:
        ns = {}
        exec(code, ns)
        ok = True
        for args, expected in tests:
            try:
                if ns["f"](*args) != expected:
                    ok = False
                    break
            except Exception:
                ok = False
                break
        if not ok:
            killed += 1
    score = round(killed / len(mutants), 2) if mutants else 0.0
    return (killed, score)

